//! Check whether C++ `std::vector<int>` constructors can be represented as Rust overloads.
//!
//! ### Limitations
//!
//! This experiment fixes the element type to C++ `int`; it does not test generic overloads.
//! C++ allocation exceptions are not translated into Rust errors.

#![allow(unused_braces, reason = "Generated by overload! macro")]

use cpp::cpp;
use splat_overload::overload;
use std::ffi::{c_int, c_size_t, c_void};

cpp! {{
    #include <vector>
    #include <cstddef>
}}

/// Owns a C++ `std::vector<int>`; its pointer stays private so callers cannot replace it.
pub struct StdVector(*mut c_void);

#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
impl StdVector {
    fn empty() -> StdVector {
        let vector = unsafe {
            cpp!([] -> *mut c_void as "std::vector<int>*" {
                return new std::vector<int>();
            })
        };
        StdVector(vector)
    }

    fn repeat_default(count: c_size_t) -> StdVector {
        let vector = unsafe {
            cpp!([count as "size_t"] -> *mut c_void as "std::vector<int>*" {
                return new std::vector<int>(count);
            })
        };
        StdVector(vector)
    }

    fn repeat_with(count: c_size_t, value: c_int) -> StdVector {
        let vector = unsafe {
            cpp!([count as "size_t", value as "int"] -> *mut c_void as "std::vector<int>*" {
                return new std::vector<int>(count, value);
            })
        };
        StdVector(vector)
    }

    fn from_slice(items: &[c_int]) -> StdVector {
        let count = items.len();
        let items = items.as_ptr();
        let vector = unsafe {
            cpp!([items as "const int*", count as "size_t"] -> *mut c_void as "std::vector<int>*" {
                // An empty Rust slice may have a dangling pointer. Use a real C++ object
                // for its empty iterator range, avoiding arithmetic on that pointer.
                const int empty = 0;
                const int* first = count == 0 ? &empty : items;
                return new std::vector<int>(first, first + count);
            })
        };
        StdVector(vector)
    }
}

// cpp_build must see cpp! calls directly in the source, outside overload! expansion.
// ### Constructor coverage
//
// Compared against the [C++ vector constructor declarations](https://eel.is/c++draft/vector.overview).
// The default, count, count-and-value, and iterator-pair constructors are exercised
// through Rust `new` overloads. Explicit allocator arguments, including
// allocator-only and allocator-extended copy/move constructors, are excluded by the
// contribution task's allocator-overload rule.
//
// The remaining constructors are deferred, not demonstrated to be inexpressible:
// - Copy construction (`vector(const vector&)`) needs an overload borrowing another
//   wrapper and tests showing an independent copy. It is outside this initial set of
//   four constructors; `new(&StdVector)` is a possible extension.
// - Move construction (`vector(vector&&)`) needs an explicit ownership mapping and
//   tests for the moved-from wrapper. A Rust move of this wrapper only transfers its
//   pointer and does not call the C++ move constructor. The existing forward-list
//   example's mutable-reference approach is a possible extension to investigate.
// - Initializer-list construction is not exercised by the slice overload: that helper
//   calls the iterator-pair constructor. Rust has no direct `std::initializer_list`
//   type; a distinct wrapper or fixed-arity overloads, as in the forward-list example,
//   would need separate tests. Mapping it to the same slice signature would not let
//   callers select between the two C++ constructors.
// - C++23 `vector(std::from_range, range)` needs a range bridge and a distinct tag or
//   argument type to distinguish it from the existing slice overload. It is deferred
//   pending that design; the current slice test does not exercise this constructor.
//
// These scope choices require mentor review; this is not complete constructor coverage.
//
overload! {
    impl StdVector {
        /// Construct an empty vector.
        pub fn new() -> StdVector {
            StdVector::empty()
        }

        /// Construct `count` default-initialized integer elements (zeros).
        ///
        /// ### Ergonomics
        ///
        /// Counts use `c_size_t`; callers can use an explicit argument type to select
        /// this overload.
        pub fn new(count: c_size_t) -> StdVector {
            StdVector::repeat_default(count)
        }

        /// Construct `count` copies of `value`, following C++ argument order.
        ///
        /// ### Ergonomics
        ///
        /// Counts use `c_size_t`, while elements use `c_int`. Callers can use explicit
        /// argument types to select this overload.
        pub fn new(count: c_size_t, value: c_int) -> StdVector {
            StdVector::repeat_with(count, value)
        }

        /// Copy a slice using the C++ iterator-pair constructor.
        ///
        /// ### Limitations
        ///
        /// Represents the iterator-pair constructor using contiguous input, rather
        /// than exposing arbitrary C++ iterators.
        ///
        /// ### Ergonomics
        ///
        /// Arrays must be converted to slices explicitly. A possible improvement is
        /// to accept array references directly, avoiding that conversion. This needs
        /// investigation into the macro's support for array lengths and overload selection.
        pub fn new(items: &[c_int]) -> StdVector {
            StdVector::from_slice(items)
        }
    }
}

impl Drop for StdVector {
    fn drop(&mut self) {
        let vector = self.0;
        // Each constructor allocates a distinct vector. The wrapper cannot be copied,
        // and no accessor exposes its pointer, so this deletes it exactly once.
        unsafe {
            cpp!([vector as "std::vector<int>*"] {
                delete vector;
            })
        }
    }
}

#[cfg(test)]
impl StdVector {
    fn len(&self) -> c_size_t {
        let vector = self.0;
        unsafe {
            cpp!([vector as "const std::vector<int>*"] -> c_size_t as "size_t" {
                return vector->size();
            })
        }
    }

    fn get(&self, index: c_size_t) -> Option<c_int> {
        if index >= self.len() {
            return None;
        }
        let vector = self.0;
        // The bounds check precedes the read; returning a copy avoids exposing a
        // reference into C++ storage with a Rust lifetime.
        Some(unsafe {
            cpp!([vector as "const std::vector<int>*", index as "size_t"] -> c_int as "int" {
                return (*vector)[index];
            })
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn assert_contents(vector: &StdVector, expected: &[c_int]) {
        assert_eq!(vector.len(), expected.len());
        for (index, value) in expected.iter().enumerate() {
            assert_eq!(vector.get(index), Some(*value));
        }
        assert_eq!(vector.get(expected.len()), None);
    }

    #[test]
    fn empty_constructor() {
        let vector: StdVector = StdVector::new();
        assert_contents(&vector, &[]);
    }

    #[test]
    fn count_constructor_initializes_every_element() {
        let vector: StdVector = StdVector::new(4_usize);
        assert_contents(&vector, &[0, 0, 0, 0]);
    }

    #[test]
    fn count_constructor_accepts_zero() {
        let vector: StdVector = StdVector::new(0_usize);
        assert_contents(&vector, &[]);
    }

    #[test]
    fn fill_constructor_preserves_count_and_value_order() {
        let vector: StdVector = StdVector::new(3_usize, 7 as c_int);
        assert_contents(&vector, &[7, 7, 7]);

        let negative: StdVector = StdVector::new(2_usize, -5 as c_int);
        assert_contents(&negative, &[-5, -5]);
    }

    #[test]
    fn fill_constructor_accepts_zero_count() {
        let vector: StdVector = StdVector::new(0_usize, 7 as c_int);
        assert_contents(&vector, &[]);
    }

    #[test]
    fn range_constructor_copies_the_selected_elements() {
        let vector: StdVector = {
            let mut source: Vec<c_int> = vec![99, 2, 5, 9, 100];
            let vector: StdVector = StdVector::new(&source[1..4]);
            source[2] = -1;
            assert_contents(&vector, &[2, 5, 9]);
            vector
        };
        // The C++ vector owns its elements even after the source has been dropped.
        assert_contents(&vector, &[2, 5, 9]);
    }

    #[test]
    fn range_constructor_accepts_empty_slices() {
        let empty: &[c_int] = &[];
        let vector: StdVector = StdVector::new(empty);
        assert_contents(&vector, &[]);

        let source: [c_int; 2] = [2, 5];
        let vector: StdVector = StdVector::new(&source[2..]);
        assert_contents(&vector, &[]);
    }
}
